import{_ as i,a8 as r,o as s,c as h,ah as g,gn as p,go as b,gp as m,a as e,a3 as a,K as n,L as c}from"./chunks/framework.D9VmMSku.js";import"./chunks/theme.7j9Y6pfQ.js";const y=JSON.parse('{"title":"GlowLink：多 Agent 社媒获客系统","description":"","frontmatter":{"tags":["作坊","AI Agent","RAG","LangGraph"]},"headers":[],"relativePath":"vault/作坊/glowlink-demo.md","filePath":"vault/Workshop/glowlink-demo.md","lastUpdated":1793173648000}'),A={name:"vault/作坊/glowlink-demo.md"};function k(_,t,u,x,C,P){const l=r("VPNolebaseInlineLinkPreview"),d=r("NolebaseGitContributors"),o=r("NolebaseGitChangelog");return s(),h("div",null,[t[6]||(t[6]=g('<h1 id="glowlink-多-agent-社媒获客系统" tabindex="-1">GlowLink：多 Agent 社媒获客系统 <a class="header-anchor" href="#glowlink-多-agent-社媒获客系统" aria-label="Permalink to “GlowLink：多 Agent 社媒获客系统”">​</a></h1><blockquote><p>一个出海 SaaS 品牌的 AI Agent Demo，覆盖「内容生产 → 社媒运营 → 销售转化」全链路自动化。技术栈：LangGraph + RAG 混合检索 + MCP 跨进程工具调用。</p></blockquote><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to “架构总览”">​</a></h2><p><img src="'+p+'" alt="GlowLink 系统架构总览"></p><p><strong>核心设计</strong>：Supervisor 路由模式——一个「领导」带三个「兵」，每个 Agent 执行后必须返回 Supervisor 判断是否结束。工具权限隔离：ContentAgent 不调 CRM，SalesAgent 不调搜索。</p><hr><h2 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to “技术选型”">​</a></h2><table tabindex="0"><thead><tr><th>技术决策</th><th>选定方案</th><th>为什么选这个</th></tr></thead><tbody><tr><td>LLM</td><td>DeepSeek (deepseek-chat)</td><td>国内直连，成本低，支持 Function Calling</td></tr><tr><td>Agent 框架</td><td>LangChain + LangGraph</td><td>StateGraph 可视化编排，条件边实现动态路由</td></tr><tr><td>Agent 模式</td><td>Supervisor 路由</td><td>路由可控，出问题可精确归因</td></tr><tr><td>Embedding</td><td>BAAI/bge-small-zh-v1.5</td><td>本地离线，中文效果好，CPU 可跑</td></tr><tr><td>向量库</td><td>Chroma（内存模式）</td><td>轻量级，无需 Docker</td></tr><tr><td>Reranker</td><td>BAAI/bge-reranker-base</td><td>CrossEncoder 精排 Top-3</td></tr><tr><td>混合检索</td><td>BM25 + 向量，权重 4:6</td><td>关键词 + 语义互补</td></tr><tr><td>工具调用(进程内)</td><td>LangChain @tool</td><td>RAG 和 CRM 工具</td></tr><tr><td>工具调用(跨进程)</td><td>MCP</td><td>搜索工具走标准协议，展示解耦能力</td></tr><tr><td>UI</td><td>Streamlit</td><td>极简，链路可追踪</td></tr></tbody></table><hr><h2 id="核心亮点" tabindex="-1">核心亮点 <a class="header-anchor" href="#核心亮点" aria-label="Permalink to “核心亮点”">​</a></h2><h3 id="_1-rag-混合检索-重排序" tabindex="-1">1. RAG 混合检索 + 重排序 <a class="header-anchor" href="#_1-rag-混合检索-重排序" aria-label="Permalink to “1. RAG 混合检索 + 重排序”">​</a></h3><p>不是简单的「调 API 查向量库」，而是一个三层漏斗：</p><p><img src="'+b+'" alt="RAG Pipeline 混合检索"></p><ul><li><strong>BM25 关键词检索</strong>（权重 0.4）：精准命中「$49」「试用期」等专有名词</li><li><strong>向量语义检索</strong>（权重 0.6）：理解「怎么收费」和「定价」是同一回事</li><li><strong>BGE Reranker 重排序</strong>：Top-10 候选逐个 CrossEncoder 打分，精排取 Top-3</li><li><strong>引用溯源</strong>：每条回答附带来源文件名</li></ul><h3 id="_2-双层记忆机制" tabindex="-1">2. 双层记忆机制 <a class="header-anchor" href="#_2-双层记忆机制" aria-label="Permalink to “2. 双层记忆机制”">​</a></h3><table tabindex="0"><thead><tr><th>记忆层</th><th>实现方式</th><th>作用</th></tr></thead><tbody><tr><td>short_term_memory</td><td>LangGraph messages 字段，add_messages reducer</td><td>跨轮对话：第二轮能引用第一轮提到的信息</td></tr><tr><td>cross_agent_memory</td><td>每个 Agent 执行后写入 150 字摘要</td><td>跨 Agent 共享：SalesAgent 知道 ContentAgent 写了什么帖子</td></tr></tbody></table><h3 id="_3-工具权限隔离" tabindex="-1">3. 工具权限隔离 <a class="header-anchor" href="#_3-工具权限隔离" aria-label="Permalink to “3. 工具权限隔离”">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th style="text-align:center;">ContentAgent</th><th style="text-align:center;">SocialAgent</th><th style="text-align:center;">SalesAgent</th></tr></thead><tbody><tr><td>get_knowledge (RAG)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>search_web (MCP)</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td></tr><tr><td>save_to_crm (CRM)</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td></tr></tbody></table><blockquote><p>ContentAgent 不应调 CRM（写帖子时不该顺手录客户），SalesAgent 不应调搜索（回答价格不需要搜行业趋势）。权限隔离防止 Agent「越权操作」，是企业级 Agent 系统的关键设计。</p></blockquote><h3 id="_4-评测体系-有数据-有归因-有回归" tabindex="-1">4. 评测体系（有数据 + 有归因 + 有回归） <a class="header-anchor" href="#_4-评测体系-有数据-有归因-有回归" aria-label="Permalink to “4. 评测体系（有数据 + 有归因 + 有回归）”">​</a></h3><ul><li>3 个测试 Case 覆盖内容生成、线索识别、RAG 溯源</li><li>失败归因：路由错误 / 检索失败 / 生成偏差 / 工具未调用</li><li>回归测试：对比历史结果，追踪改进效果</li></ul><hr><h2 id="两个值得讲的「坑」" tabindex="-1">两个值得讲的「坑」 <a class="header-anchor" href="#两个值得讲的「坑」" aria-label="Permalink to “两个值得讲的「坑」”">​</a></h2><h3 id="坑-1-向量检索搜不到「-49」" tabindex="-1">坑 1：向量检索搜不到「$49」 <a class="header-anchor" href="#坑-1-向量检索搜不到「-49」" aria-label="Permalink to “坑 1：向量检索搜不到「$49」”">​</a></h3><p>用户问「多少钱」，向量检索返回的是「定价灵活」「性价比高」等泛泛描述，而不是包含「$49/月」的段落。</p><p><strong>原因</strong>：Embedding 模型对数字和符号的语义编码不够强，「多少钱」和「$49」在向量空间中距离较远。</p><p><strong>解法</strong>：引入 BM25 关键词检索做补充。BM25 基于词频匹配，对「$49」「14 天」「Instagram」等关键词命中精准。混合权重 BM25:向量 = 4:6，关键词为辅、语义为主。</p><h3 id="坑-2-agent-编造不存在的数据" tabindex="-1">坑 2：Agent 编造不存在的数据 <a class="header-anchor" href="#坑-2-agent-编造不存在的数据" aria-label="Permalink to “坑 2：Agent 编造不存在的数据”">​</a></h3><p>ContentAgent 在写帖子时，会编造「GlowLink 支持 TikTok 自动发布」等功能，这些在知识库中并不存在。</p><p><strong>解法</strong>：在每个 Agent 的 System Prompt 中加入防幻觉规则——「价格、功能、数据类信息必须来自 RAG 返回结果」「如果 RAG 没搜到，明确说暂时无法确认，禁止编造」。</p><hr><h2 id="技术决策速查" tabindex="-1">技术决策速查 <a class="header-anchor" href="#技术决策速查" aria-label="Permalink to “技术决策速查”">​</a></h2><p><img src="'+m+'" alt="技术决策概览"></p><hr><h2 id="项目信息" tabindex="-1">项目信息 <a class="header-anchor" href="#项目信息" aria-label="Permalink to “项目信息”">​</a></h2>',35)),e("ul",null,[t[3]||(t[3]=e("li",null,[e("strong",null,"类型"),a("：Demo / 概念验证")],-1)),e("li",null,[t[1]||(t[1]=e("strong",null,"源码",-1)),t[2]||(t[2]=a("：",-1)),n(l,{href:"https://github.com/star-nebula/job-demo/tree/main/social-media-agent-demo",target:"_blank",rel:"noreferrer"},{default:c(()=>[...t[0]||(t[0]=[a("GitHub",-1)])]),_:1})]),t[4]||(t[4]=e("li",null,[e("strong",null,"开发方式"),a("：全程 AI 编程工具（CodeBuddy）辅助，遵循 AI Engineering Loop")],-1)),t[5]||(t[5]=e("li",null,[e("strong",null,"技术栈"),a("：Python / LangChain + LangGraph / Chroma / Streamlit / DeepSeek / MCP")],-1))]),n(d),n(o)])}const S=i(A,[["render",k]]);export{y as __pageData,S as default};
